const results = $json.results[0].data;

const chunks = results.map(row => {
  const cols = row.row;
  return {
    heading: cols[0],
    text: cols[1],
    title: cols[2],
    section: cols[3],
    url: cols[4],
    score: cols[5]
  };
});

const context = chunks
  .map(c => `## ${c.title} â ${c.heading}\n${c.text}`)
  .join('\n\n---\n\n');

return [{
  json: {
    context,
    chunks,
    question: $('Webhook').first().json.body.question
  }
}];

const context = $input.first().json.context || '';
const question = $input.first().json.question || '';
const history = $('Webhook').first().json.body.history || [];

const messages = [
  ...history,
  {
    role: "user",
    content: "Context from Atlas documentation: " + context.replace(/\n/g, ' ') + " Question: " + question
  }
];

return [{
  json: {
    model: "claude-sonnet-4-6",
    max_tokens: 1024,
    system: `You are an expert Varonis Atlas AI Security Platform advisor helping Sales Engineers configure Atlas for their customers.

RETRIEVAL GROUNDING RULES:
- You will be provided with retrieved documentation context for each question
- Always prioritize and cite information from the provided context
- If the context covers the topic, base your answer primarily on it
- Only supplement with general knowledge when the context is clearly insufficient
- If the context does not cover the topic at all, say so explicitly before answering
- Never present information as fact if it contradicts the provided context

CRITICAL ARCHITECTURAL CONTEXT:
- AI applications do not "integrate with" Atlas in the traditional sense
- Instead, applications connect THROUGH Atlas by pointing their LLM API calls at the Atlas AI Gateway proxy URL instead of directly at the LLM provider (OpenAI, Anthropic, etc.)
- The AI Gateway is a proxy â any application that makes LLM API calls can use it by simply changing its endpoint URL
- When someone asks how to "connect" or "integrate" an app with Atlas, the answer is always: configure the app to route its LLM traffic through the AI Gateway

BEHAVIOR GUIDELINES:
- For integration questions, redirect toward AI Gateway configuration and ask what LLM the app is calling
- Use the provided documentation context as your primary source
- When context is thin, apply architectural reasoning and ask clarifying questions
- Be concise and SE-focused â your audience is technical sales staff, not developers

Use the documentation context provided with each question to give accurate, specific answers.`,
    messages: messages
  }
}];

const embedding = $('Embed Question').first().json.data[0].embedding;

const body = JSON.stringify({
  statements: [{
    statement: "CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 5, $embedding) YIELD node, score RETURN node.heading AS heading, node.text AS text, node.title AS title, node.section AS section, node.url AS url, score",
    parameters: { embedding: embedding }
  }]
});

return [{ json: { requestBody: body } }];

const claudeResponse = $input.first().json;
const answer = claudeResponse.content[0].text;
const previousMessages = $('Prepare Claude Input').first().json.messages;
const history = [...previousMessages, { role: "assistant", content: answer }];

return [{ json: { answer, history } }];
